ROOT=[dict(id='C0281',meaning='隐藏；藏起来',core='crypt-：把东西藏住，可以藏在地下，也可以把意思和信息藏起来。',image='一扇门后藏着地下空间；一句话背后藏着没说透的意思；一段密文把原内容藏在数学转换之后。',intro='希腊 kryptein 是隐藏，kryptos 是隐藏的。crypt、grotto 接地下空间的支线；cryptic 说意思不明；encrypt、decrypt 说信息的加密与解密。grotesque 经意大利洞穴与装饰艺术发展，路走得远，不能硬按现代字母拆。',forms='crypt-、crypto- 是学术构词形式；grot- 经拉丁和意大利语变化而来。apocrypha 的后半保留希腊“隐藏”支线，-ph- 在英语读 /f/。各词分别借入或派生，不是都由英语 crypt 再造。',branches=[['地下空间与怪诞装饰','crypt、grotto、grotesque、grotesquely'],['意义隐晦与真伪存疑','cryptic、cryptically、apocrypha、apocryphal'],['保护信息与分析密码','encrypt、encryption、encrypted、decrypt、decryption、cryptanalysis、cryptology、cryptography、cryptographic']],contrasts='cryptic 不等于技术上 encrypted；grotto 不必是墓室；apocryphal 不是一口咬定已经证伪。decrypt 与 encrypt 是现代构词的一对，别凭反义关系猜造词先后。',practice='区分一条看不懂的暗示、一份真正加密的文件和一则广为流传却没有可靠出处的故事。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/crypt','https://www.etymonline.com/word/grotesque','https://www.etymonline.com/word/apocrypha','https://www.merriam-webster.com/dictionary/encrypt','https://csrc.nist.gov/glossary/term/cryptanalysis'])]
assert keep==set(r['family'])-set(excluded)
